from jinja2 import DictLoader, Environment, select_autoescape

TEMPLATES = {
"base.html": """<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='theme-color' content='#25213a'><title>{% block title %}ReadTrackr{% endblock %}</title><style>
:root{--ink:#25213a;--muted:#746f82;--paper:#faf8f5;--surface:#fff;--line:#e9e3dc;--plum:#65478e;--plum-dark:#473169;--lav:#f0eafa;--gold:#f5b942;--red:#b42318;--shadow:0 12px 30px rgba(54,39,75,.08);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 95% 0,#f2edfb 0,transparent 25rem),var(--paper);color:var(--ink);line-height:1.45}a{color:inherit;text-decoration:none}header{position:sticky;top:0;z-index:5;backdrop-filter:blur(14px);background:rgba(250,248,245,.9);border-bottom:1px solid var(--line)}.topbar{max-width:1180px;margin:auto;padding:14px 28px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{font-weight:850;letter-spacing:-.04em;font-size:1.25rem}.brand span{color:var(--plum)}nav{display:flex;gap:4px;align-items:center}nav a{padding:8px 10px;border-radius:9px;color:var(--muted);font-size:.93rem;font-weight:650}nav a:hover,nav a:focus{background:var(--lav);color:var(--plum)}nav form{margin:0}.button,button{display:inline-flex;align-items:center;justify-content:center;gap:7px;border:0;border-radius:10px;background:var(--plum);color:#fff;padding:11px 14px;font:inherit;font-weight:750;cursor:pointer;box-shadow:0 5px 12px rgba(101,71,142,.18);transition:.18s transform,.18s background}.button:hover,button:hover{background:var(--plum-dark);transform:translateY(-1px)}.button.ghost,nav button{background:transparent;box-shadow:none;color:var(--muted);padding:8px 10px}.button.ghost:hover,nav button:hover{background:#f0ece7;color:var(--ink);transform:none}main{max-width:1180px;margin:auto;padding:42px 28px 64px}.eyebrow{margin:0 0 6px;color:var(--plum);font-size:.73rem;letter-spacing:.13em;font-weight:800;text-transform:uppercase}.page-head{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:28px}.page-head h1,.hero h1{font-size:clamp(2rem,4vw,3.25rem);letter-spacing:-.055em;line-height:1.03;margin:0}.subtle,.muted{color:var(--muted)}.hero{padding:12px 0 26px}.stat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:42px}.stat{padding:21px;border:1px solid var(--line);border-radius:17px;background:rgba(255,255,255,.72);box-shadow:var(--shadow)}.stat b{display:block;font-size:2.15rem;letter-spacing:-.05em}.stat span{color:var(--muted);font-size:.9rem;font-weight:650}.section-head{display:flex;justify-content:space-between;align-items:baseline;gap:12px;margin:25px 0 13px}.section-head h2{margin:0;font-size:1.27rem;letter-spacing:-.025em}.book-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(215px,1fr));gap:15px}.book-card{min-height:128px;display:flex;gap:13px;padding:13px;border:1px solid var(--line);background:var(--surface);border-radius:15px;box-shadow:0 3px 10px rgba(54,39,75,.035);transition:.18s transform,.18s box-shadow}.book-card:hover{transform:translateY(-3px);box-shadow:var(--shadow)}.cover{width:60px;height:88px;flex:0 0 auto;overflow:hidden;display:grid;place-items:center;border-radius:9px;background:linear-gradient(145deg,#e1d6ef,#cbbce0);color:#5e457c;font-size:1.45rem;font-weight:800}.cover img{width:100%;height:100%;object-fit:cover}.book-copy{min-width:0}.book-copy strong{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;font-size:.98rem;line-height:1.25}.book-copy small{display:block;color:var(--muted);margin-top:5px}.stars{color:#cf8c13;letter-spacing:1px}.filters{padding:12px;border:1px solid var(--line);border-radius:14px;background:#fff;display:flex;gap:10px;margin-bottom:22px}.filters input{flex:1}.form{max-width:650px;padding:22px;border:1px solid var(--line);border-radius:17px;background:#fff;box-shadow:var(--shadow);display:grid;gap:16px}label{font-size:.88rem;font-weight:750;display:grid;gap:7px}input,select,textarea{width:100%;border:1px solid #ded7d0;border-radius:10px;background:#fff;padding:11px 12px;font:inherit;color:var(--ink)}input:focus,select:focus,textarea:focus{outline:3px solid #e8dff5;border-color:#a98dce}textarea{min-height:130px}.detail{padding:22px;border-radius:18px;background:#fff;border:1px solid var(--line);display:flex;gap:24px;margin-bottom:20px}.detail .cover{width:138px;height:200px;font-size:2.5rem}.detail h1{margin:4px 0;font-size:2rem;letter-spacing:-.04em}.notice{padding:15px 17px;border-radius:12px;background:#f2edf9;color:#49346a;margin:18px 0}.error{padding:14px 16px;border-radius:12px;background:#fef0ee;color:var(--red);margin:18px 0}.auth{max-width:410px;margin:8vh auto;padding:32px;background:#fff;border:1px solid var(--line);border-radius:22px;box-shadow:var(--shadow)}.auth h1{margin-top:0;font-size:2rem;letter-spacing:-.04em}.auth form{display:grid;gap:16px}.import-table{width:100%;border-collapse:collapse;background:#fff;border:1px solid var(--line);border-radius:14px;overflow:hidden;margin:18px 0}.import-table th,.import-table td{padding:11px 13px;text-align:left;border-bottom:1px solid var(--line)}.import-table th{background:#f8f5f1;color:var(--muted);font-size:.78rem;text-transform:uppercase;letter-spacing:.06em}.recommendation{display:grid;grid-template-columns:96px 1fr;gap:18px;padding:18px;background:#fff;border:1px solid var(--line);border-radius:17px;box-shadow:var(--shadow);margin:14px 0}.recommendation .cover{width:96px;height:140px}.rec-meta{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.match{font-size:.78rem;font-weight:850;color:var(--plum);background:var(--lav);padding:5px 8px;border-radius:999px}.chips{display:flex;flex-wrap:wrap;gap:6px;margin:11px 0}.chip{font-size:.77rem;color:#5b5167;background:#f3f0ed;padding:4px 8px;border-radius:999px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:15px}.actions button{font-size:.88rem;padding:9px 11px}.actions .secondary{background:#eee8f5;color:var(--plum);box-shadow:none}.actions .quiet{background:#f4f1ed;color:#5f5965;box-shadow:none}.cover-page{max-width:700px;padding:30px;border:1px solid var(--line);border-radius:20px;background:#fff;box-shadow:var(--shadow)}.cover-page h1{margin-top:0;letter-spacing:-.04em}
@media(max-width:700px){.topbar{padding:12px 17px;display:block}.brand{display:block;margin-bottom:10px}nav{overflow-x:auto;gap:3px;padding-bottom:2px}nav a,nav button{font-size:.82rem;white-space:nowrap;padding:7px 8px}main{padding:28px 17px 46px}.page-head{align-items:flex-start;flex-direction:column;margin-bottom:22px}.page-head .button{width:100%}.stat-grid{gap:9px;margin-bottom:30px}.stat{padding:14px 11px;border-radius:14px}.stat b{font-size:1.55rem}.stat span{font-size:.76rem}.book-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.book-card{min-height:112px;gap:10px;padding:10px;border-radius:13px}.cover{width:47px;height:69px;font-size:1.1rem}.book-copy strong{font-size:.85rem}.book-copy small{font-size:.77rem;margin-top:3px}.filters{display:grid}.filters button{width:100%}.detail{padding:16px;gap:15px}.detail .cover{width:86px;height:126px}.detail h1{font-size:1.45rem}.recommendation{grid-template-columns:70px 1fr;gap:13px;padding:13px}.recommendation .cover{width:70px;height:102px}.recommendation h2{font-size:1.2rem;margin:5px 0}.recommendation p{font-size:.92rem}.import-table{display:block;overflow-x:auto}.cover-page{padding:22px}.auth{margin:4vh auto;padding:25px}}
</style></head><body><header><div class='topbar'><a class='brand' href='/'>Read<span>Trackr</span></a>{% if request.session.get('user') %}<nav><a href='/library'>Library</a><a href='/metadata'>Covers</a><a href='/recommendations'>For you</a><a href='/import'>Import</a><a href='/export/csv'>Export</a><form method='post' action='/logout'><button>Log out</button></form></nav>{% endif %}</div></header><main>{% block content %}{% endblock %}</main></body></html>""",
"login.html": "{% extends 'base.html' %}{% block content %}<section class='auth'><p class='eyebrow'>Private library</p><h1>Your next chapter starts here.</h1><p class='subtle'>Sign in to your personal reading archive.</p>{% if error %}<p class='error'>{{error}}</p>{% endif %}<form method='post'><label>Username<input name='username' required autofocus autocomplete='username'></label><label>Password<input name='password' type='password' required autocomplete='current-password'></label><button>Sign in</button></form></section>{% endblock %}",
"cards.html": "<div class='book-grid'>{% for entry in entries %}<a class='book-card' href='/books/{{entry.book.id}}'><div class='cover'>{% if entry.book.thumbnail_url %}<img src='{{entry.book.thumbnail_url}}' alt='Cover of {{entry.book.title}}'>{% else %}&#128214;{% endif %}</div><div class='book-copy'><strong>{{entry.book.title}}</strong><small>{{entry.book.authors}}</small><small>{{entry.status.replace('_',' ')|title}}{% if entry.rating %}<span class='stars'> · {{'★' * entry.rating}}</span>{% endif %}</small></div></a>{% else %}<p class='muted'>Nothing here yet.</p>{% endfor %}</div>",
"dashboard.html": "{% extends 'base.html' %}{% block content %}<section class='hero'><p class='eyebrow'>Your reading life</p><div class='page-head'><h1>Welcome to your library.</h1><a class='button' href='/books/new'>+ Add a book</a></div></section><div class='stat-grid'><article class='stat'><b>{{entries|selectattr('status','equalto','read')|list|length}}</b><span>Books read</span></article><article class='stat'><b>{{current|length}}</b><span>Reading now</span></article><article class='stat'><b>{{entries|selectattr('rating')|list|length}}</b><span>Books rated</span></article></div><div class='section-head'><h2>Current reads</h2>{% if current %}<a class='muted' href='/library?status=currently_reading'>View all</a>{% endif %}</div>{% set entries=current %}{% include 'cards.html' %}<div class='section-head'><h2>Recently read</h2><a class='muted' href='/library'>Full library →</a></div><p class='subtle'>A quick look at your six most recently finished books.</p>{% set entries=recent %}{% include 'cards.html' %}{% endblock %}",
"library.html": "{% extends 'base.html' %}{% block content %}<div class='page-head'><div><p class='eyebrow'>{{entries|length}} books shown</p><h1>Library</h1></div><a class='button' href='/books/new'>+ Add a book</a></div><form class='filters'><input name='q' value='{{q}}' placeholder='Search title or author'><select name='status'><option value=''>All statuses</option>{% for s in ['read','currently_reading','want_to_read','paused','abandoned','dismissed','not_interested'] %}<option value='{{s}}' {% if selected==s %}selected{% endif %}>{{s.replace('_',' ')|title}}</option>{% endfor %}</select><button>Filter</button></form>{% include 'cards.html' %}{% endblock %}",
"book_form.html": "{% extends 'base.html' %}{% block content %}<div class='page-head'><div><p class='eyebrow'>Library</p><h1>Add a book</h1></div></div><form class='form' method='post'><label>Title<input name='title' required></label><label>Author<input name='authors'></label><label>Status<select name='status'>{% for s in ['want_to_read','currently_reading','read','paused','abandoned'] %}<option value='{{s}}'>{{s.replace('_',' ')|title}}</option>{% endfor %}</select></label><label>Rating<input name='rating' type='number' min='1' max='5' placeholder='Optional, 1–5'></label><button>Add to library</button></form>{% endblock %}",
"book.html": "{% extends 'base.html' %}{% block content %}<article class='detail'><div class='cover'>{% if book.thumbnail_url %}<img src='{{book.thumbnail_url}}' alt='Cover of {{book.title}}'>{% else %}&#128214;{% endif %}</div><div><p class='eyebrow'>{{entry.status.replace('_',' ')|title}}</p><h1>{{book.title}}</h1><p class='subtle'>{{book.authors}}</p>{% if book.description %}<p>{{book.description}}</p>{% endif %}</div></article><form class='form' method='post'><label>Status<select name='status'>{% for s in ['read','currently_reading','want_to_read','paused','abandoned','dismissed','not_interested'] %}<option value='{{s}}' {% if entry.status==s %}selected{% endif %}>{{s.replace('_',' ')|title}}</option>{% endfor %}</select></label><label>Rating<select name='rating'><option value=''>Not rated</option>{% for r in range(1,6) %}<option value='{{r}}' {% if entry.rating==r %}selected{% endif %}>{{r}} star{{'s' if r>1}}</option>{% endfor %}</select></label><label>Private notes<textarea name='notes' placeholder='Thoughts, quotes, or reminders…'>{{entry.private_notes or ''}}</textarea></label><button>Save changes</button></form>{% endblock %}",
"import.html": "{% extends 'base.html' %}{% block content %}<div class='cover-page'><p class='eyebrow'>Goodreads</p><h1>Import your reading history.</h1><p class='subtle'>Preview your export before importing. A re-import updates books already in your library.</p>{% if not preview and not summary %}<form class='form' method='post' action='/import/preview' enctype='multipart/form-data'><label>Goodreads CSV<input type='file' name='csv_file' accept='.csv,text/csv' required></label><button>Preview import</button></form>{% endif %}{% if preview %}<div class='notice'><b>{{total}}</b> rows found. Check this sample, then import.</div><table class='import-table'><tr><th>Title</th><th>Author</th><th>Shelf</th><th>Rating</th></tr>{% for row in preview %}<tr><td>{{row['Title']}}</td><td>{{row['Author']}}</td><td>{{row['Exclusive Shelf']}}</td><td>{{row['My Rating']}}</td></tr>{% endfor %}</table><form method='post' action='/import/commit'><button>Import {{total}} books</button></form>{% endif %}{% if summary %}<div class='notice'><b>Import complete.</b> Added {{summary.added}}, updated {{summary.updated}}, skipped {{summary.skipped}}.</div><a class='button' href='/library'>View library</a>{% endif %}</div>{% endblock %}",
"metadata.html": "{% extends 'base.html' %}{% block content %}<section class='cover-page'><p class='eyebrow'>Cover backfill</p><h1>Bring your shelves to life.</h1><p class='subtle'><b>{{missing}}</b> books are waiting to be checked. Each refresh checks up to 25 with Google Books, then Open Library as a fallback.</p>{% if unavailable %}<p class='subtle'><b>{{unavailable}}</b> books have already been checked without a public cover match. You can add their covers manually later.</p>{% endif %}{% if summary %}<div class='notice'><b>Refresh complete.</b> Checked {{summary.checked}} · Covers found {{summary.updated}} · No match {{summary.not_found}} · Errors {{summary.errors}}</div>{% endif %}<form method='post' action='/metadata/refresh'><button>{% if missing %}Refresh next cover batch{% else %}Check remaining covers again{% endif %}</button></form></section>{% endblock %}",
"recommendations.html": "{% extends 'base.html' %}{% block content %}<div class='page-head'><div><p class='eyebrow'>Personal picks</p><h1>For you</h1><p class='subtle'>A fresh manual refresh uses your ratings and reading history. Reasons are spoiler-free.</p></div><form method='post' action='/recommendations/refresh'><button>Refresh picks</button></form></div>{% if error %}<p class='error'>{{error}}</p>{% endif %}{% for rec in recs %}<article class='recommendation'><div class='cover'>{% if rec.book.thumbnail_url %}<img src='{{rec.book.thumbnail_url}}' alt='Cover of {{rec.book.title}}'>{% else %}&#128214;{% endif %}</div><div><div class='rec-meta'><span class='match'>{{(rec.score * 100)|round|int}}% match</span><span class='subtle'>{{rec.book.authors}}</span></div><h2>{{rec.book.title}}</h2><p>{{rec.reason}}</p>{% if rec.matched_preferences %}<div class='chips'>{% for preference in rec.matched_preferences.split(', ') %}<span class='chip'>{{preference}}</span>{% endfor %}</div>{% endif %}<div class='actions'><form method='post' action='/recommendations/{{rec.id}}/want_to_read'><button>Want to read</button></form><form method='post' action='/recommendations/{{rec.id}}/dismissed'><button class='secondary'>Dismiss</button></form><form method='post' action='/recommendations/{{rec.id}}/not_interested'><button class='quiet'>Not interested</button></form></div></div></article>{% else %}<section class='cover-page'><h2>No picks yet.</h2><p class='subtle'>Rate a few books, refresh covers, then request recommendations.</p></section>{% endfor %}{% endblock %}"
}
environment = Environment(loader=DictLoader(TEMPLATES), autoescape=select_autoescape())
